                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                for k in range(abs(dr) + 1):
                    r, c = r1 + k * sr, c1 + k * sc
                    if grid[r][c] == 6:
                        active_sixes.add((r, c))
