def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    activated = set()

    # Connect pairs of diagonal 1s. Any 6 on such a segment activates
    # its perpendicular diagonal.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            for k in range(abs(dr) + 1):
                r, c = r1 + k * sr, c1 + k * sc
                if grid[r][c] == 6:
                    activated.add((r, c))
                elif grid[r][c] == bg:
                    out[r][c] = 1

    # Draw the opposite diagonal through each activated 6.
    for r, c in activated:
        for sr, sc in ((1, -1), (-1, 1)):
            rr, cc = r, c
            while 0 <= rr - sr < h and 0 <= cc - sc < w:
                rr -= sr
                cc -= sc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == bg:
                    out[rr][cc] = 6
                rr += sr
                cc += sc

    return out
